import{_ as p,a0 as s,w as o,s as b,ao as i,I as a,x as u,a1 as r,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊] | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊] | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊] | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊] | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/Daily Ubuntu Tips – Upgrade To Ubuntu 14.04 (Trusty Tahr) From 13.10","title":"Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊]","tag":"201402","desc":""},"relativePath":"201402/Daily Ubuntu Tips – Upgrade To Ubuntu 14.04 (Trusty Tahr) From 13.10.md","filePath":"[post].md"}'),d={name:"201402/Daily Ubuntu Tips – Upgrade To Ubuntu 14.04 (Trusty Tahr) From 13.10.md"};function T(l,t,U,m,g,f){const n=s("Link");return o(),b("div",null,[t[11]||(t[11]=i(`<h1 id="ubuntu-每日贴士-从ubuntu-13-10升级到14-04-trusty-tahr-值得信赖的塔尔羊" tabindex="-1">Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊] <a class="header-anchor" href="#ubuntu-每日贴士-从ubuntu-13-10升级到14-04-trusty-tahr-值得信赖的塔尔羊" aria-label="Permalink to “Ubuntu 每日贴士:从Ubuntu 13.10升级到14.04(Trusty Tahr) [值得信赖的塔尔羊]”">​</a></h1><p>虽然Ubuntu 14.04 按计划不会近期发布正式版，但那些想要尝试最新软件和系统的人现在可以从Ubuntu 13.10 就地升级到 14.04了。</p><p>Ubuntu 14.04 目前计划在2014.4.17发布，但是你不必等那么长的时间来升级尝试。这个简要的教程给你展示了如何就地从Ububtu 13.10 升级到 14.04。</p><p>就地升级是你在已存在的Ubuntu上运行update-manager命令来升级到下一版。它允许你保留你大多数的文档，设定和一些程序。</p><p>大多数就地升级依赖于一个可靠的网络连接。没有良好稳定的连接,可能无法使用这个方法升级Ubuntu。</p><p>如果你无法使用网络升级，你还可以通过CD/DVD盘来就地升级。这个方法允许你不通过网络连接离线升级Ubuntu。</p><h3 id="升级到-ubuntu-14-04" tabindex="-1">升级到 Ubuntu 14.04 <a class="header-anchor" href="#升级到-ubuntu-14-04" aria-label="Permalink to “升级到 Ubuntu 14.04”">​</a></h3><p>为了升级到Ubuntu 14.04, 你首先要给你要升级的电脑做好准备工作。请运行下面的命令更新所有存在的包和内核。</p><pre><code>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade &amp;&amp; sudo apt-get autoremove
</code></pre><p>完成上述更新后，你可能需要重启来在升级前应用新的包和内核。</p><p>接着，按下键盘上的<strong>Alt+F2</strong>键来打开Ubuntu上的命令窗口。当窗口打开后，输入下面的命令并按下<strong>回车</strong>。</p><pre><code>update-manager –d
</code></pre><p>Ubuntu接着应该带着升级选项会打开update-manager。按下<strong>Upgrade</strong> 开始升级你的机器。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/ubuntu1404upgrade.png" alt=""></p><p>就是这样!</p><p>等待Ubuntu完成下载并安装所有的更新包。当一切完成时,你会被提示重启计算机。</p><p>享受吧!</p><hr>`,18)),a("p",null,[t[1]||(t[1]=u("via: ",-1)),r(n,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-upgrade-to-ubuntu-14-04-trusty-tahr-from-13-10/"},{default:e(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-upgrade-to-ubuntu-14-04-trusty-tahr-from-13-10/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=u("译者：",-1)),r(n,{href:"https://github.com/geekpi"},{default:e(()=>[...t[2]||(t[2]=[u("geekpi",-1)])]),_:1}),t[5]||(t[5]=u(" 校对：",-1)),r(n,{href:"https://github.com/wxy"},{default:e(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=u("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原创翻译，",-1)),r(n,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[u("Linux中国",-1)])]),_:1}),t[10]||(t[10]=u(" 荣誉推出",-1))])])}const C=p(d,[["render",T]]);export{_ as __pageData,C as default};
